@startuml

class Ingredient {
  + name : string
  + measuringUnit : string
  + quantityInStock : float
}

class Dish {
  + name : string
  + identifier : int
}

class Table {
  + identifier : int
  + maxPeople : int
}

class Meal {
  + date : date
  + startTime : time
  + endTime : time
}

class Waiter {
  + identifier : int
  + name : string
  + address : string
  + phoneNumber : string
}

class Client {
  + taxIdentificationNumber : string
  + name : string
  + address : string
}

class MealDish {
  + quantity : float
}

class DishIngredient {
  + quantity : float
}

Dish "1" -- "1..*" DishIngredient
DishIngredient "1" -- "1" Ingredient

Dish "1" -- "0..*" MealDish
Meal "1" -- "1..*" MealDish
Meal "1" -- "1" Table
Meal "1" -- "0..1" Client
Meal "1" -- "1" Waiter

@enduml

